Q: How could I specifically get the name of a window that I want to focus and not have to sort through them oddly? A: <p>This issue isn't with PyWin32, it is how the Windows API enumerates windows. The <a href="https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-enumwindows" rel="nofollow noreferrer">EnumWindows</a> will return all windows, the controls of a window (buttons, text fields, menus, labels(these are all windows)) the taskbar, system tray, including the desktop itself. These are all windows attached to explorer.exe. It is almost impossible to find the hWnd of the window &quot;you see&quot; on the screen using EnumWindows.</p>
<p><a href="https://pypi.org/project/pyvda/" rel="nofollow noreferrer">pyvda</a> uses a COM interfaces that deals specifically with the virtual desktops (what you see on your screen), and only returns the hWnds of the parent windows itself.</p>
<p>The following class will return any parent window that is attached to a 'Spotify' executable. I've also stripped the need for PyWin32, and used Python's builtin ctypes for accessing the Windows API.</p>
<pre class="lang-py prettyprint-override"><code>import ctypes
from ctypes import wintypes

from psutil import Process
from pyvda import AppView
from pyvda.com_defns import IApplicationView
from pyvda.utils import Managers


# https://learn.microsoft.com/en-us/windows/win32/api/winuser/ns-winuser-windowplacement
# typedef struct tagWINDOWPLACEMENT {
#   UINT  length;
#   UINT  flags;
#   UINT  showCmd;
#   POINT ptMinPosition;
#   POINT ptMaxPosition;
#   RECT  rcNormalPosition;
#   RECT  rcDevice;
# } WINDOWPLACEMENT;
class WINDOWPLACEMENT(ctypes.Structure):
    _fields_ = [
        ('length', wintypes.UINT),
        ('flags', wintypes.UINT),
        ('showCmd', wintypes.UINT),
        ('ptMinPosition', wintypes.POINT),
        ('ptMaxPosition', wintypes.POINT),
        ('rcNormalPosition', wintypes.RECT),
    ]


class AppProcess(Process, AppView):
    __MANAGERS = Managers()

    @property
    def caption(self) -&gt; str:
        text_len = self.__GetWindowTextLength(self.hwnd) + 1
        text_buffer = ctypes.create_unicode_buffer(text_len)

        self.__GetWindowText(self.hwnd, text_buffer, text_len)
        return text_buffer.value

    def __init__(self, view: IApplicationView):
        self.__init_win32_api_function_prototypes()

        AppView.__init__(self, view = view)
        Process.__init__(self, pid = self.__get_pid(self.hwnd))

    @classmethod
    def find_instances(cls, name: str) -&gt; list[AppProcess]:
        instances: list[AppProcess] = []
        for view in cls.__MANAGERS.view_collection.GetViewsByZOrder().iter(IApplicationView):
            if bool(view.GetShowInSwitchers()):
                if (instance := AppProcess(view = view)).name() == name:
                    instances.append(instance)
        return instances

    def __get_pid(self, hWnd: int) -&gt; int:
        pid = wintypes.DWORD()
        tid = self.__GetWindowThreadProcessId(hWnd, ctypes.byref(pid))
        if tid == 0:
            raise ctypes.WinError(ctypes.get_last_error())
        return pid.value

    def __init_win32_api_function_prototypes(self):
        user32 = ctypes.WinDLL('user32', use_last_error = True)

        # https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-getwindowthreadprocessid
        # DWORD GetWindowThreadProcessId(
        #   [in]            HWND    hWnd,
        #   [out, optional] LPDWORD lpdwProcessId
        # );
        self.__GetWindowThreadProcessId = user32.GetWindowThreadProcessId
        self.__GetWindowThreadProcessId.argtypes = [wintypes.HWND, wintypes.LPDWORD]
        self.__GetWindowThreadProcessId.restype = wintypes.DWORD

        # https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-getwindowtextw
        # int GetWindowTextW(
        #   [in]  HWND   hWnd,
        #   [out] LPWSTR lpString,
        #   [in]  int    nMaxCount
        # );
        self.__GetWindowText = user32.GetWindowTextW
        self.__GetWindowText.argtypes = [wintypes.HWND, wintypes.LPWSTR, wintypes.INT]
        self.__GetWindowText.restype = wintypes.BOOL

        # https://learn.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-getwindowtextlengthw
        # int GetWindowTextLengthW(
        #   [in] HWND hWnd
        # );
        self.__GetWindowTextLength = user32.GetWindowTextLengthW
        self.__GetWindowTextLength.argtypes = [wintypes.HWND]
        self.__GetWindowTextLength.restype = wintypes.INT


if __name__ == '__main__':
    for process in AppProcess.find_instances(name = 'Spotify.exe'):
        print(process.caption)
</code></pre>

Q: Connection refused for localhost:9990 &amp; localhost:8080 A: <h2>Updating SecurityConfig for Spring Boot 3</h2>
<p>In Spring Boot 3 (Spring Security 6), the <code>WebSecurityConfigurerAdapter</code> is deprecated. You should now use a <code>SecurityFilterChain</code> bean like this:</p>
<pre><code>@Bean
public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
    http
        .csrf(csrf -&gt; csrf.disable())
        .authorizeHttpRequests(auth -&gt; auth
            .requestMatchers(&quot;/api/public/**&quot;).permitAll()
            .anyRequest().authenticated()
        )
        .httpBasic(Customizer.withDefaults());
    return http.build();
}
</code></pre>
